/// Reads values in the format of Flutter's standard message codec.
private struct CacheMessagesPigeonInteropReader {
  private let data: NSData
  private let bytes: UnsafeRawBufferPointer
  private var position = 0

  init(_ data: NSData) {
    self.data = data
    self.bytes = UnsafeRawBufferPointer(start: data.bytes, count: data.length)
  }

  var isAtEnd: Bool { position >= bytes.count }

  mutating func readByte() -> UInt8 {
    let byte = bytes[position]
    position += 1
    return byte
  }

  mutating func readRaw<T: FixedWidthInteger>(_ type: T.Type) -> T {
    let value = bytes.loadUnaligned(fromByteOffset: position, as: T.self)
    position += MemoryLayout<T>.size
    return T(littleEndian: value)
  }

  mutating func readSize() -> Int {
    let byte = readByte()
    if byte < CacheMessagesPigeonInteropCodec.sizeUInt16 {
      return Int(byte)
    } else if byte == CacheMessagesPigeonInteropCodec.sizeUInt16 {
      return Int(readRaw(UInt16.self))
    }
    return Int(readRaw(UInt32.self))
  }

  mutating func readAlignment(_ alignment: Int) {
    let mod = position % alignment
    if mod != 0 {
      position += alignment - mod
    }
  }

  mutating func readTypedData<T>(_ type: T.Type, alignment: Int) -> [T] {
    let count = readSize()
    readAlignment(alignment)
    let byteCount = count * MemoryLayout<T>.stride
    let result = [T](unsafeUninitializedCapacity: count) { buffer, initializedCount in
      if byteCount > 0 {
        UnsafeMutableRawBufferPointer(buffer).copyMemory(
          from: UnsafeRawBufferPointer(rebasing: bytes[position..<(position + byteCount)]))
      }
      initializedCount = count
    }
    position += byteCount
    return result
  }

  mutating func readValue() -> Any? {
    return readValue(ofType: readByte())
  }

  mutating func readValue(ofType type: UInt8) -> Any? {
    switch type {
    case CacheMessagesPigeonInteropCodec.typeNull:
      return nil
    case CacheMessagesPigeonInteropCodec.typeTrue:
      return true
    case CacheMessagesPigeonInteropCodec.typeFalse:
      return false
    case CacheMessagesPigeonInteropCodec.typeInt32:
      return Int64(readRaw(Int32.self))
    case CacheMessagesPigeonInteropCodec.typeInt64:
      return readRaw(Int64.self)
    case CacheMessagesPigeonInteropCodec.typeLargeInt, CacheMessagesPigeonInteropCodec.typeString:
      let count = readSize()
      let string = String(
        decoding: UnsafeRawBufferPointer(rebasing: bytes[position..<(position + count)]),
        as: UTF8.self)
      position += count
      return string
    case CacheMessagesPigeonInteropCodec.typeFloat64:
      readAlignment(8)
      return Double(bitPattern: readRaw(UInt64.self))
    case CacheMessagesPigeonInteropCodec.typeUint8List:
      return readTypedData(UInt8.self, alignment: 1)
    case CacheMessagesPigeonInteropCodec.typeInt32List:
      return readTypedData(Int32.self, alignment: 4)
    case CacheMessagesPigeonInteropCodec.typeInt64List:
      return readTypedData(Int64.self, alignment: 8)
    case CacheMessagesPigeonInteropCodec.typeFloat64List:
      return readTypedData(Float64.self, alignment: 8)
    case CacheMessagesPigeonInteropCodec.typeList:
      let count = readSize()
      var list: [Any?] = []
      list.reserveCapacity(count)
      for _ in 0..<count {
        list.append(readValue())
      }
      return list
    case CacheMessagesPigeonInteropCodec.typeMap:
      let count = readSize()
      var map: [AnyHashable?: Any?] = [:]
      map.reserveCapacity(count)
      for _ in 0..<count {
        let key = readValue() as? AnyHashable
        map[key] = readValue()
      }
      return map
    case CacheMessagesPigeonInteropCodec.typeFloat32List:
      return readTypedData(Float32.self, alignment: 4)
    default:
      return readCustomValue(ofType: type)
    }
  }

  mutating func readListHeader() {
    _ = readByte()
    _ = readSize()
  }

  mutating func read<T>(_ type: T.Type) -> T {
    return readValue() as! T
  }

  mutating func read<E>(_ type: [E].Type) -> [E] {
    let tag = readByte()
    guard tag == CacheMessagesPigeonInteropCodec.typeList else {
      return readValue(ofType: tag) as! [E]
    }
    let count = readSize()
    var list: [E] = []
    list.reserveCapacity(count)
    for _ in 0..<count {
      list.append(readValue() as! E)
    }
    return list
  }

  mutating func read<E>(_ type: [E]?.Type) -> [E]? {
    if bytes[position] == CacheMessagesPigeonInteropCodec.typeNull {
      position += 1
      return nil
    }
    return read([E].self)
  }

  mutating func read<K: Hashable, V>(_ type: [K: V].Type) -> [K: V] {
    let tag = readByte()
    guard tag == CacheMessagesPigeonInteropCodec.typeMap else {
      return readValue(ofType: tag) as! [K: V]
    }
    let count = readSize()
    var map: [K: V] = [:]
    map.reserveCapacity(count)
    for _ in 0..<count {
      let key = readValue() as! K
      map[key] = (readValue() as! V)
    }
    return map
  }

  mutating func read<K: Hashable, V>(_ type: [K: V]?.Type) -> [K: V]? {
    if bytes[position] == CacheMessagesPigeonInteropCodec.typeNull {
      position += 1
      return nil
    }
    return read([K: V].self)
  }


  mutating func readWireCacheManagerConfig() -> WireCacheManagerConfig {
    readListHeader()
    return WireCacheManagerConfig(
      maxDiskCacheBytes: read(Int64.self),
      maxEntries: read(Int64.self),
      defaultTtlSeconds: read(Int64.self),
      evictionPolicy: read(WireCacheEvictionPolicy.self),
      cacheSubdirectory: read(String.self),
      maxConcurrentDownloads: read(Int64.self),
      connectTimeoutMs: read(Int64.self),
      readTimeoutMs: read(Int64.self),
      defaultHeaders: read([String: String].self),
      respectHttpCacheHeaders: read(Bool.self),
      autoTrimOnWrite: read(Bool.self)
    )
  }

  mutating func readWireCacheRequest() -> WireCacheRequest {
    readListHeader()
    return WireCacheRequest(
      url: read(String.self),
      customKey: read(String?.self),
      tag: read(String?.self),
      fileExtension: read(String?.self),
      headers: read([String: String].self),
      ttlSeconds: read(Int64?.self),
      forceRefresh: read(Bool.self),
      fallbackToCacheOnError: read(Bool.self),
      pinned: read(Bool.self),
      checksumAlgorithm: read(WireCacheChecksumAlgorithm.self),
      expectedChecksum: read(String?.self)
    )
  }

  mutating func readWireCacheEntry() -> WireCacheEntry {
    readListHeader()
    return WireCacheEntry(
      key: read(String.self),
      url: read(String.self),
      filePath: read(String.self),
      sizeBytes: read(Int64.self),
      createdAtMs: read(Int64.self),
      lastAccessedAtMs: read(Int64.self),
      expiresAtMs: read(Int64.self),
      hitCount: read(Int64.self),
      tag: read(String?.self),
      mimeType: read(String?.self),
      eTag: read(String?.self),
      lastModified: read(String?.self),
      checksum: read(String?.self),
      checksumAlgorithm: read(WireCacheChecksumAlgorithm.self),
      pinned: read(Bool.self)
    )
  }

  mutating func readWireCacheFetchResult() -> WireCacheFetchResult {
    readListHeader()
    return WireCacheFetchResult(
      entry: read(WireCacheEntry?.self),
      source: read(WireCacheResultSource.self),
      httpStatusCode: read(Int64?.self),
      elapsedMs: read(Int64.self)
    )
  }

  mutating func readWireCacheProgressEvent() -> WireCacheProgressEvent {
    readListHeader()
    return WireCacheProgressEvent(
      key: read(String.self),
      url: read(String.self),
      state: read(WireCacheTransferState.self),
      bytesReceived: read(Int64.self),
      totalBytes: read(Int64.self),
      filePath: read(String?.self),
      errorMessage: read(String?.self)
    )
  }

  mutating func readWireCacheStats() -> WireCacheStats {
    readListHeader()
    return WireCacheStats(
      totalEntries: read(Int64.self),
      totalBytes: read(Int64.self),
      expiredEntries: read(Int64.self),
      pinnedEntries: read(Int64.self),
      maxDiskCacheBytes: read(Int64.self),
      cacheDirectoryPath: read(String.self),
      hitCount: read(Int64.self),
      missCount: read(Int64.self),
      evictionCount: read(Int64.self),
      bytesByTag: read([String: Int64].self)
    )
  }

  mutating func readWireCachePlatformCapabilities() -> WireCachePlatformCapabilities {
    readListHeader()
    return WireCachePlatformCapabilities(
      platformName: read(String.self),
      supportsFileSystemPaths: read(Bool.self),
      supportsConditionalHttpRevalidation: read(Bool.self),
      supportsNativeCryptoHash: read(Bool.self),
      supportsLowDiskSpaceNotifications: read(Bool.self),
      storageMechanism: read(String.self),
      defaultCacheRootPath: read(String.self)
    )
  }

  mutating func readCustomValue(ofType type: UInt8) -> Any? {
    switch type {
    case 129:
      guard let raw = readValue() as? Int64 else { return nil }
      return WireCacheChecksumAlgorithm(rawValue: Int(raw))
    case 130:
      guard let raw = readValue() as? Int64 else { return nil }
      return WireCacheEvictionPolicy(rawValue: Int(raw))
    case 131:
      guard let raw = readValue() as? Int64 else { return nil }
      return WireCacheResultSource(rawValue: Int(raw))
    case 132:
      guard let raw = readValue() as? Int64 else { return nil }
      return WireCacheTransferState(rawValue: Int(raw))
    case 133:
      return readWireCacheManagerConfig()
    case 134:
      return readWireCacheRequest()
    case 135:
      return readWireCacheEntry()
    case 136:
      return readWireCacheFetchResult()
    case 137:
      return readWireCacheProgressEvent()
    case 138:
      return readWireCacheStats()
    case 139:
      return readWireCachePlatformCapabilities()
    default:
      preconditionFailure("Unsupported type: \(type)")
    }
  }
}

/// Encodes and decodes the buffers that native interop calls pass to and from
/// Dart, in the same format as the message codec.
private enum CacheMessagesPigeonInteropCodec {
  static let typeNull: UInt8 = 0
  static let typeTrue: UInt8 = 1
  static let typeFalse: UInt8 = 2
  static let typeInt32: UInt8 = 3
  static let typeInt64: UInt8 = 4
  static let typeLargeInt: UInt8 = 5
  static let typeFloat64: UInt8 = 6
  static let typeString: UInt8 = 7
  static let typeUint8List: UInt8 = 8
  static let typeInt32List: UInt8 = 9
  static let typeInt64List: UInt8 = 10
  static let typeFloat64List: UInt8 = 11
  static let typeList: UInt8 = 12
  static let typeMap: UInt8 = 13
  static let typeFloat32List: UInt8 = 14
  static let sizeUInt16: UInt8 = 254
  static let sizeUInt32: UInt8 = 255

  static func encode(_ value: Any?) -> NSData {
    var writer = CacheMessagesPigeonInteropWriter()
    writer.writeValue(value)
    return writer.bytes.withUnsafeBytes { NSData(bytes: $0.baseAddress, length: $0.count) }
  }

  static func encodeOrNil(_ value: Any?) -> NSData? {
    return CacheMessagesPigeonInternal.isNullish(value) ? nil : encode(value)
  }

  static func encode(_ write: (inout CacheMessagesPigeonInteropWriter) -> Void) -> NSData {
    var writer = CacheMessagesPigeonInteropWriter()
    write(&writer)
    return writer.bytes.withUnsafeBytes { NSData(bytes: $0.baseAddress, length: $0.count) }
  }

  static func decode(_ data: NSData?) -> Any? {
    guard let data = data else {
      return nil
    }
    var reader = CacheMessagesPigeonInteropReader(data)
    return reader.readValue()
  }

  static func decodeArguments(_ data: NSData) -> [Any?] {
    return decode(data) as! [Any?]
  }

  static func typedData<T>(_ data: NSData, as type: T.Type) -> [T] {
    let count = data.length / MemoryLayout<T>.stride
    return [T](unsafeUninitializedCapacity: count) { buffer, initializedCount in
      if data.length > 0 {
        UnsafeMutableRawBufferPointer(buffer).copyMemory(
          from: UnsafeRawBufferPointer(start: data.bytes, count: count * MemoryLayout<T>.stride))
      }
      initializedCount = count
    }
  }

  static func data<T>(_ array: [T]) -> NSData {
    return array.withUnsafeBytes { NSData(bytes: $0.baseAddress, length: $0.count) }
  }
}


class CacheHostApiInstanceTracker {
  static var instancesOfCacheHostApi = [String: [CacheHostApiSetup]]()
  /// Guards the registrations, which Native Interop calls can read from any thread.
  static let lock = NSLock()
}
/// Generated protocol from Pigeon that represents a handler of messages from Flutter.
protocol CacheHostApi: AnyObject {
  func configure(config: WireCacheManagerConfig) async throws
  func downloadFile(request: WireCacheRequest) async throws -> WireCacheFetchResult
  func prefetchAll(requests: [WireCacheRequest]) async throws -> [WireCacheEntry]
  func cancelDownload(keyOrUrl: String) throws -> Bool
  func getFileFromCache(keyOrUrl: String, ignoreExpired: Bool) async throws -> WireCacheEntry?
  func readCacheBytes(keyOrUrl: String, ignoreExpired: Bool) async throws -> [UInt8]?
  func containsKey(keyOrUrl: String, ignoreExpired: Bool) async throws -> Bool
  func putBytes(key: String, bytes: [UInt8], url: String?, fileExtension: String?, mimeType: String?, tag: String?, ttlSeconds: Int64?, pinned: Bool) async throws -> WireCacheEntry
  func putFile(key: String, sourceFilePath: String, url: String?, fileExtension: String?, mimeType: String?, tag: String?, ttlSeconds: Int64?, pinned: Bool) async throws -> WireCacheEntry
  func setPinned(keyOrUrl: String, pinned: Bool) async throws -> Bool
  func removeFile(keyOrUrl: String) async throws -> Bool
  func removeByTag(tag: String) async throws -> Int64
  func removeExpired() async throws -> Int64
  func trimToSize(maxBytes: Int64) async throws -> Int64
  func clearAll(includePinned: Bool) async throws -> Int64
  func listEntries(tag: String?, includeExpired: Bool) async throws -> [WireCacheEntry]
  func getStats() async throws -> WireCacheStats
  func getCapabilities() throws -> WireCachePlatformCapabilities
}

/// Generated setup class from Pigeon to register implemented CacheHostApi classes.
@objc class CacheHostApiSetup: NSObject {
  private var api: CacheHostApi?
  override init() {}
  private func resolveApi() throws -> CacheHostApi {
    CacheHostApiInstanceTracker.lock.lock()
    let registeredApi = api
    CacheHostApiInstanceTracker.lock.unlock()
    guard let currentApi = registeredApi else {
      throw PigeonError(
        code: "unregistered-instance",
        message: "CacheHostApi has not been registered.",
        details: nil
      )
    }
    return currentApi
  }
  /// The engine key this wrapper was registered with. Set before the wrapper is published.
  private var engineKey: Int64 = Int64.min

  #if canImport(Flutter) || canImport(FlutterMacOS)
    /// Registers `api` under `name` (or the default instance when `name` is omitted).
    ///
    /// The registration is tied to its engine: unregistering it for one engine leaves
    /// other engines' registrations in place, and Dart code running on an engine uses
    /// the instance registered for that engine when it is known.
    ///
    /// The registration is associated with the engine that owns `registrar`. The same
    /// `api` registered from different engines is tracked as separate registrations.
    static func register(api: CacheHostApi, registrar: FlutterPluginRegistrar, name: String = CacheMessagesPigeonInternal.defaultInstanceName) {
      register(api: api, engineKey: PigeonEngineKeys.key(for: registrar), name: name)
    }

    /// Removes `api` from the registrations under `name` (or the default instance
    /// when `name` is omitted), leaving other registrations in place.
    ///
    /// Instances are matched by identity. Does nothing if `api` is not registered.
    ///
    /// Prefers the registration made from the engine that owns `registrar`, and
    /// otherwise removes the registration of `api` under `name` if exactly one engine
    /// holds it.
    static func unregister(api: CacheHostApi, registrar: FlutterPluginRegistrar, name: String = CacheMessagesPigeonInternal.defaultInstanceName) {
      unregister(api: api, engineKey: PigeonEngineKeys.key(for: registrar), name: name)
    }
  #endif

  fileprivate static func register(api: CacheHostApi, engineKey: Int64, name: String) {
    CacheHostApiInstanceTracker.lock.lock()
    defer { CacheHostApiInstanceTracker.lock.unlock() }
    var list = CacheHostApiInstanceTracker.instancesOfCacheHostApi[name] ?? []
    if let index = list.firstIndex(where: { $0.api === api && $0.engineKey == engineKey }) {
      list.append(list.remove(at: index))
    } else {
      let wrapper = CacheHostApiSetup()
      wrapper.engineKey = engineKey
      wrapper.api = api
      list.append(wrapper)
    }
    CacheHostApiInstanceTracker.instancesOfCacheHostApi[name] = list
  }

